k'){body=`<div class="panel"><h3>Idle floor stock</h3>${d.units.filter(u=>u.status==='AVAILABLE').map(u=>`<div class="record"><div><h4>${u.asset_tag} · ${u.model}</h4><span class="muted">Currently ${u.location_name}</span></div><div class="row"><select data-dest="${u.id}">${d.locations.filter(l=>l.id!==u.location_id).map(l=>`<option value="${l.id}">${l.name}</option>`).join('')}</select><button class="btn" data-transfer="${u.id}">Request stamped move</button></div></div>`).join('')}</div>`}else if(role==='night_auditor'){body=`<div class="panel"><h3>Immutable activity book</h3>${auditTable(d.audit)}</div>`}else if(role==='insurance_liaison'){body=`<div class="panel"><h3>Signed hull binds</h3>${d.binds?.length?`<pre>${JSON.stringify(d.binds,null,2)}</pre>`:'<div class="empty">No hull binds have been recorded.</div>'}</div>`}else{body=`<div class="panel"><h3>Fleet overview</h3><p class="muted">Lot runners can see where gear rests, but cannot drive transfers or work the counter.</p><div class="grid">${d.units.map(card).join('')}</div></div>`}$('#content').innerHTML=`<div class="section" id="workspace"><div class="section-head"><div><p class="eyebrow" style="color:var(--rust)">${label(role)}</p><h2>${title}</h2></div></div><div class="role-banner">Signed in as <b>${state.me.full_name}</b>. This workspace only offers work assigned to your role.</div>${body}</div>`;bindOps(d)}catch(e){flash(e.message,true)}}
